 */
public interface BackgroundCheckClient {

    /** POST /background-checks (재시도 포함) */
    Result create(ExternalCreateRequest request);

    /** GET /background-checks/{checkId} (단발, 재시도 없음 — 폴링 주기가 재시도 역할) */
