23	@Slf4j
24	@Component
25	public class RestBackgroundCheckClient implements BackgroundCheckClient {
26	    private final RestClient rest;
27	    private final BgcProperties props;
28	    private final ObjectMapper objectMapper;
29	
30	    public RestBackgroundCheckClient(BgcProperties props, ObjectMapper objectMapper) {
31	        this.props = props;
32	        this.objectMapper = objectMapper;
33	        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();
34	        factory.setConnectTimeout(Duration.ofMillis(props.connectTimeoutMs()));
35	        factory.setReadTimeout(Duration.ofMillis(props.readTimeoutMs()));
36	        this.rest = RestClient.builder()
37	                .baseUrl(props.baseUrl())
38	                .requestFactory(factory)
39	                .build();
40	    }
41	
42	    @Override
43	    public Result create(ExternalCreateRequest request) {
44	        Result last = null;
45	        for (int attempt = 1; attempt <= props.postMaxAttempts(); attempt++) {
46	            last = exchange(() -> rest.post().uri("/background-checks")
47	                    .contentType(MediaType.APPLICATION_JSON).body(request)
48	                    .retrieve().body(String.class), attempt);
49	            if (last.ok() || last.badRequest()) return last;     // 4xx 는 재시도 무의미
50	            if (attempt < props.postMaxAttempts()) sleep(props.postRetryBackoffMs());
