60	    private interface Call { String run(); }
61	
62	    private Result exchange(Call call, int attempt) {
63	        try {
64	            String body = call.run();
65	            ExternalCheck parsed = body == null ? null : objectMapper.readValue(body, ExternalCheck.class);
66	            return new Result(200, parsed, null, attempt);
67	        } catch (RestClientResponseException e) {
68	            int code = e.getStatusCode().value();
69	            String msg = "HTTP " + code + " " + summarize(e.getResponseBodyAsString());
70	            log.warn("bgcheck api {} (attempt {})", msg, attempt);
71	            return new Result(code, null, msg, attempt);
72	        } catch (ResourceAccessException e) {
73	            String msg = "timeout/network: " + e.getMostSpecificCause().getClass().getSimpleName();
74	            log.warn("bgcheck api {} (attempt {})", msg, attempt);
75	            return new Result(0, null, msg, attempt);
