54	            throw ApiException.locked("LOCKED", "로그인 실패 횟수를 초과해 잠긴 계정입니다. 관리자에게 임시 비밀번호 재발급을 요청하세요.");
55	        }
56	        Instant now = clock.instant();
57	        if (!passwordEncoder.matches(password, e.getPasswordHash())) {
58	            int threshold = props.auth().lockThreshold();
59	            e.setFailedLoginCount(e.getFailedLoginCount() + 1);
60	            e.setUpdatedAt(now);
61	            if (e.getFailedLoginCount() >= threshold) {
62	                e.setLocked(true);
63	                sessions.deleteAllByEmployeeId(e.getEmployeeId());
64	                audits.save(AuditLog.builder().actorId(e.getEmployeeId()).action(AuditAction.ACCOUNT_LOCKED)
65	                        .targetEmployeeId(e.getEmployeeId()).detail(Map.of("failedLoginCount", e.getFailedLoginCount())).createdAt(now).build());
66	                throw ApiException.locked("LOCKED", "로그인 실패 횟수를 초과해 계정이 잠겼습니다. 관리자에게 임시 비밀번호 재발급을 요청하세요.");
67	            }
68	            throw ApiException.unauthorized("INVALID_CREDENTIALS",
69	                    "사번 또는 비밀번호가 올바르지 않습니다. (" + e.getFailedLoginCount() + "/" + threshold + ")");
70	        }
71	        e.setFailedLoginCount(0);
72	        Session s = Session.builder()
73	                .sessionId(tokens.sessionId())
74	                .employeeId(e.getEmployeeId())
75	                .createdAt(now)
76	                .lastAccessedAt(now)
77	                .expiresAt(now.plus(Duration.ofMinutes(props.session().idleMinutes())))
78	                .build();
79	        return sessions.save(s);
80	    }
81	
82	    @Transactional
83	    public void logout(String sessionId) {
84	        sessions.deleteById(sessionId);
85	    }
86	
87	    /**
88	     * 세션 검증 + 슬라이딩 연장. 만료·절대상한·퇴사·잠금이면 세션을 지우고 빈 값.
89	     * 필터가 매 요청마다 호출한다 (F6: 퇴사 처리 = 세션 삭제 → 다음 요청부터 여기서 걸림).
90	     */
91	    @Transactional
92	    public Optional<AuthenticatedUser> resolve(String sessionId) {
93	        Optional<Session> found = sessions.findById(sessionId);
94	        if (found.isEmpty()) return Optional.empty();
95	        Session s = found.get();
96	        Instant now = clock.instant();
97	        Instant absoluteLimit = s.getCreatedAt().plus(Duration.ofHours(props.session().absoluteHours()));
98	        if (now.isAfter(s.getExpiresAt()) || now.isAfter(absoluteLimit)) {
99	            sessions.delete(s);
100	            return Optional.empty();
101	        }
102	        Optional<Employee> emp = employees.findById(s.getEmployeeId());
103	        if (emp.isEmpty() || emp.get().getStatus() != EmployeeStatus.ACTIVE || emp.get().isLocked()) {
104	            sessions.delete(s);
105	            return Optional.empty();
106	        }
107	        s.setLastAccessedAt(now);
108	        s.setExpiresAt(now.plus(Duration.ofMinutes(props.session().idleMinutes())));
109	        Employee e = emp.get();
110	        return Optional.of(new AuthenticatedUser(e.getEmployeeId(), e.getName(), e.getRole(), e.isMustChangePassword(), s.getSessionId()));
111	    }
112	
113	    @Transactional
114	    public Employee changePassword(String employeeId, String currentPassword, String newPassword) {
115	        Employee e = employees.findById(employeeId)
116	                .orElseThrow(() -> ApiException.notFound("NOT_FOUND", "직원을 찾을 수 없습니다."));
117	        if (!passwordEncoder.matches(currentPassword, e.getPasswordHash())) {
118	            throw ApiException.badRequest("INVALID_CURRENT_PASSWORD", "현재 비밀번호가 올바르지 않습니다.");
119	        }
120	        if (currentPassword.equals(newPassword)) {
121	            throw ApiException.badRequest("SAME_AS_TEMP", "임시(현재) 비밀번호와 다른 비밀번호를 사용해야 합니다.");
122	        }
123	        e.setPasswordHash(passwordEncoder.encode(newPassword));
124	        e.setMustChangePassword(false);
125	        e.setUpdatedAt(clock.instant());
126	        return e;
127	    }
128	
129	    @Transactional(readOnly = true)
130	    public Employee getEmployee(String employeeId) {
131	        return employees.findById(employeeId)
132	                .orElseThrow(() -> ApiException.notFound("NOT_FOUND", "직원을 찾을 수 없습니다."));
133	    }
134	}

