13	
14	import java.time.Duration;
15	
16	/**
17	 * 외부 Background Check API 실제 호출.
18	 * 실측(MEASUREMENTS) 반영:
19	 *  - 응답이 ~30s 부근에 몰리므로 read timeout 은 그보다 길게 (yml).
20	 *  - 503 본문의 retryAfter(30) 는 헤더로는 오지 않고, 값이 항상 30 이라 재시도 간격 근거로 쓰지 않는다.
21	 *  - POST 는 실측상 거의 항상 201 이지만 명세의 5xx 대비 짧은 재시도를 둔다. GET 은 폴링 주기가 재시도 역할.
22	 */
23	@Slf4j
24	@Component
25	public class RestBackgroundCheckClient implements BackgroundCheckClient {
26	    private final RestClient rest;
27	    private final BgcProperties props;
28	    private final ObjectMapper objectMapper;
29	
30	    public RestBackgroundCheckClient(BgcProperties props, ObjectMapper objectMapper) {
31	        this.props = props;
32	        this.objectMapper = objectMapper;
33	        SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();
34	        factory.setConnectTimeout(Duration.ofMillis(props.connectTimeoutMs()));
35	        factory.setReadTimeout(Duration.ofMillis(props.readTimeoutMs()));
36	        this.rest = RestClient.builder()
37	                .baseUrl(props.baseUrl())
38	                .requestFactory(factory)
39	                .build();
40	    }
41	
42	    @Override
43	    public Result create(ExternalCreateRequest request) {
44	        Result last = null;
45	        for (int attempt = 1; attempt <= props.postMaxAttempts(); attempt++) {
46	            last = exchange(() -> rest.post().uri("/background-checks")
47	                    .contentType(MediaType.APPLICATION_JSON).body(request)
48	                    .retrieve().body(String.class), attempt);
49	            if (last.ok() || last.badRequest()) return last;     // 4xx 는 재시도 무의미
50	            if (attempt < props.postMaxAttempts()) sleep(props.postRetryBackoffMs());
51	        }
52	        return last;
53	    }
54	
55	    @Override
56	    public Result get(String checkId) {
57	        return exchange(() -> rest.get().uri("/background-checks/{id}", checkId).retrieve().body(String.class), 1);
58	    }
59	
60	    private interface Call { String run(); }
61	
62	    private Result exchange(Call call, int attempt) {
63	        try {
64	            String body = call.run();
65	            ExternalCheck parsed = body == null ? null : objectMapper.readValue(body, ExternalCheck.class);
66	            return new Result(200, parsed, null, attempt);
67	        } catch (RestClientResponseException e) {
68	            int code = e.getStatusCode().value();
69	            String msg = "HTTP " + code + " " + summarize(e.getResponseBodyAsString());
70	            log.warn("bgcheck api {} (attempt {})", msg, attempt);
71	            return new Result(code, null, msg, attempt);
72	        } catch (ResourceAccessException e) {
73	            String msg = "timeout/network: " + e.getMostSpecificCause().getClass().getSimpleName();
74	            log.warn("bgcheck api {} (attempt {})", msg, attempt);
75	            return new Result(0, null, msg, attempt);
76	        } catch (Exception e) {
77	            String msg = "parse error: " + e.getClass().getSimpleName();
78	            log.warn("bgcheck api {} (attempt {})", msg, attempt);
79	            return new Result(0, null, msg, attempt);
80	        }
81	    }
82	
83	    private static String summarize(String body) {
84	        if (body == null) return "";
85	        String s = body.replaceAll("\\s+", " ").trim();
86	        return s.length() > 120 ? s.substring(0, 120) + "…" : s;
87	    }
88	
89	    private static void sleep(long ms) {
90	        try {
91	            Thread.sleep(ms);
92	        } catch (InterruptedException ie) {
93	            Thread.currentThread().interrupt();
94	        }
95	    }
96	}

