43	    /** F4 성명 파싱 규칙: 첫 글자 = 성, 나머지 = 이름. 복성 사전 없음 (planning.md). */
44	    public static String[] parseName(String name) {
45	        String t = name.trim();
46	        return new String[]{t.substring(0, 1), t.substring(1)};
47	    }
48	
49	    // ---------- 조회 ----------
50	
51	    @Transactional(readOnly = true)
52	    public MeProfile me(String employeeId) {
53	        return MeProfile.from(get(employeeId));
54	    }
55	
56	    @Transactional(readOnly = true)
57	    public List<EmployeeListItem> list(String status) {
58	        List<Employee> rows = (status == null || status.isBlank() || "ALL".equalsIgnoreCase(status))
59	                ? employees.findAllByOrderByEmployeeIdAsc()
60	                : employees.findAllByStatusOrderByEmployeeIdAsc(parseStatus(status));
61	        return rows.stream()
62	                .map(e -> EmployeeListItem.from(e, backgroundChecks.latestStatus(e.getEmployeeId()).orElse(null)))
63	                .toList();
64	    }
65	
66	    @Transactional(readOnly = true)
67	    public EmployeeDetail detail(String employeeId) {
68	        return toDetail(get(employeeId));
69	    }
70	
71	    @Transactional(readOnly = true)
72	    public List<HistoryItem> history(String employeeId) {
73	        get(employeeId);
74	        return Stream.concat(
75	                        changeLogs.findAllByEmployeeIdOrderByChangedAtDesc(employeeId).stream().map(HistoryItem::change),
76	                        audits.findAllByTargetEmployeeIdOrderByCreatedAtDesc(employeeId).stream().map(HistoryItem::audit))
77	                .sorted(Comparator.comparing(HistoryItem::at).reversed())
78	                .toList();
79	    }
