86	        Employee e = get(employeeId);
87	        List<Change> changes = List.of(
88	                new Change("phone", e.getPhone(), req.phone(), e::setPhone),
89	                new Change("address", e.getAddress(), req.address(), e::setAddress));
90	        apply(e, changes, employeeId);
91	        return MeProfile.from(e);
92	    }
