95	    @Transactional
96	    public EmployeeDetail adminUpdate(String employeeId, AdminUpdateEmployeeRequest req, String actor) {
97	        Employee e = get(employeeId);
98	        if (e.getStatus() == EmployeeStatus.RESIGNED) {
99	            throw ApiException.conflict("RESIGNED", "퇴사 처리된 직원은 수정할 수 없습니다.");
100	        }
101	        List<Change> changes = new ArrayList<>();
102	        if (req.name() != null) {
103	            changes.add(new Change("name", e.getName(), req.name(), v -> {
104	                String[] p = parseName(v);
105	                e.setName(v);
106	                e.setLastName(p[0]);
107	                e.setFirstName(p[1]);
108	            }));
109	        }
110	        if (req.birthDate() != null) changes.add(new Change("birthDate", str(e.getBirthDate()), str(req.birthDate()), v -> e.setBirthDate(LocalDate.parse(v))));
111	        if (req.phone() != null) changes.add(new Change("phone", e.getPhone(), req.phone(), e::setPhone));
112	        if (req.address() != null) changes.add(new Change("address", e.getAddress(), req.address(), e::setAddress));
113	        if (req.department() != null) changes.add(new Change("department", e.getDepartment(), req.department(), e::setDepartment));
114	        if (req.position() != null) changes.add(new Change("position", e.getPosition(), req.position(), e::setPosition));
115	        if (req.hireDate() != null) changes.add(new Change("hireDate", str(e.getHireDate()), str(req.hireDate()), v -> e.setHireDate(LocalDate.parse(v))));
116	        if (req.role() != null) changes.add(new Change("role", e.getRole().name(), req.role().name(), v -> e.setRole(Role.valueOf(v))));
117	        apply(e, changes, actor);
118	        return toDetail(e);
119	    }
